     3→ *
     4→ * A fixed bottom bar with workout control buttons: play/pause, skip interval, and stop.
     5→ * Provides haptic feedback on button press and disabled states when no session is active.
     6→ *
     7→ * Features:
     8→ * - Play/Pause toggle button based on current session state
     9→ * - Skip interval button (only enabled during workouts with intervals)
    10→ * - Stop button with confirmation (see T033 for confirmation implementation)
    11→ * - Disabled state when no active session
    12→ * - Haptic feedback on press based on user settings
    13→ * - Accessible with proper ARIA labels
    14→ */
    15→
    16→import React, { useCallback } from 'react';
    17→import { View, StyleSheet, ViewStyle } from 'react-native';
    18→import { useSafeAreaInsets } from 'react-native-safe-area-context';
    19→import Icon from 'react-native-vector-icons/Ionicons';
    20→import { useTheme } from '@/theme';
    21→import { shadows } from '@/theme/spacing';
    22→import { IconButton, type IconButtonVariant } from './IconButton';
    23→import { useHaptics } from '@/hooks/useHaptics';
    24→import {
    25→  useSessionStore,
    26→  selectIsSessionActive,
    27→  selectIsPaused,
    28→  selectCanPause,
    29→  selectCanResume,
    30→  selectCanSkip,
    31→  selectCanStop,
    32→  selectIsWorkout,
    33→} from '@/stores/sessionStore';
    34→
    35→/**
    36→ * WorkoutControlBar props
    37→ */
    38→export interface WorkoutControlBarProps {
    39→  /** Callback when pause is pressed */
    40→  onPause?: () => void;
    41→  /** Callback when resume is pressed */
    42→  onResume?: () => void;
    43→  /** Callback when skip is pressed */
    44→  onSkip?: () => void;
    45→  /** Callback when stop is pressed */
    46→  onStop?: () => void;
    47→  /** Whether the pause action is loading */
    48→  isPauseLoading?: boolean;
    49→  /** Whether the skip action is loading */
    50→  isSkipLoading?: boolean;
    51→  /** Whether the stop action is loading */
    52→  isStopLoading?: boolean;
    53→  /** Custom style for the container */
    54→  style?: ViewStyle;
    55→  /** Test ID for testing */
    56→  testID?: string;
    57→}
    58→
    59→/**
    60→ * WorkoutControlBar Component
    61→ *
    62→ * A fixed bottom control bar for workout actions. The bar appears at the bottom
    63→ * of the screen with buttons for pause/resume, skip interval, and stop.
    64→ *
    65→ * The buttons are automatically enabled/disabled based on the current session state:
    66→ * - Pause: Enabled when session is active and not paused
    67→ * - Resume: Enabled when session is active and paused
    68→ * - Skip: Enabled during workouts when not on the last interval
    69→ * - Stop: Enabled when any session is active
    70→ *
    71→ * @example
    72→ * ```tsx
    73→ * <WorkoutControlBar
    74→ *   onPause={handlePause}
    75→ *   onResume={handleResume}
    76→ *   onSkip={handleSkip}
    77→ *   onStop={handleStop}
    78→ * />
    79→ * ```
    80→ */
    81→export function WorkoutControlBar({
    82→  onPause,
    83→  onResume,
    84→  onSkip,
    85→  onStop,
    86→  isPauseLoading = false,
    87→  isSkipLoading = false,
    88→  isStopLoading = false,
    89→  style,
    90→  testID,
    91→}: WorkoutControlBarProps): React.JSX.Element {
    92→  const { colors, spacing } = useTheme();
    93→  const insets = useSafeAreaInsets();
    94→  const { impactHaptic, warningHaptic } = useHaptics();
    95→
    96→  // Session state selectors
    97→  const isSessionActive = useSessionStore(selectIsSessionActive);
    98→  const isPaused = useSessionStore(selectIsPaused);
    99→  const canPause = useSessionStore(selectCanPause);
   100→  const canResume = useSessionStore(selectCanResume);
   101→  const canSkip = useSessionStore(selectCanSkip);
   102→  const canStop = useSessionStore(selectCanStop);
   103→  const isWorkout = useSessionStore(selectIsWorkout);
   104→
   105→  // Determine if controls should be globally disabled (no active session)
   106→  const isDisabled = !isSessionActive;
   107→
   108→  // Handle play/pause button press
   109→  const handlePlayPausePress = useCallback(() => {
   110→    impactHaptic();
   111→
   112→    if (isPaused && onResume) {
   113→      onResume();
   114→    } else if (!isPaused && onPause) {
   115→      onPause();
   116→    }
   117→  }, [isPaused, onPause, onResume, impactHaptic]);
   118→
   119→  // Handle skip button press
   120→  const handleSkipPress = useCallback(() => {
   121→    impactHaptic();
   122→    onSkip?.();
   123→  }, [onSkip, impactHaptic]);
   124→
   125→  // Handle stop button press
   126→  const handleStopPress = useCallback(() => {
   127→    warningHaptic();
   128→    onStop?.();
   129→  }, [onStop, warningHaptic]);
   130→
   131→  // Determine play/pause button state
   132→  const playPauseIcon = isPaused ? 'play' : 'pause';
   133→  const playPauseLabel = isPaused ? 'Resume workout' : 'Pause workout';
   134→  const playPauseVariant: IconButtonVariant = 'primary';
   135→  const isPlayPauseDisabled = isDisabled || (isPaused ? !canResume : !canPause);
   136→
   137→  // Skip button is only enabled during workouts with remaining intervals
   138→  const isSkipDisabled = isDisabled || !isWorkout || !canSkip;
   139→  const skipVariant: IconButtonVariant = 'default';
   140→
   141→  // Stop button is enabled whenever there's an active session
   142→  const isStopDisabled = isDisabled || !canStop;
   143→  const stopVariant: IconButtonVariant = 'danger';
   144→
   145→  // Container style with safe area padding
   146→  const containerStyle: ViewStyle = {
   147→    paddingBottom: Math.max(insets.bottom, spacing.md),
   148→  };
   149→
   150→  return (
   151→    <View
   152→      style={[
   153→        styles.container,
   154→        { backgroundColor: colors.surface, borderTopColor: colors.border },
   155→        shadows.md,
   156→        containerStyle,
   157→        style,
   158→      ]}
   159→      testID={testID}
   160→      accessibilityRole="toolbar"
   161→      accessibilityLabel="Workout controls"
   162→    >
   163→      <View style={[styles.buttonContainer, { gap: spacing.lg }]}>
   164→        {/* Play/Pause Button */}
   165→        <IconButton
   166→          icon={<Icon name={playPauseIcon} />}
   167→          variant={playPauseVariant}
   168→          size="large"
   169→          circular
   170→          onPress={handlePlayPausePress}
   171→          disabled={isPlayPauseDisabled}
   172→          loading={isPauseLoading}
   173→          accessibilityLabel={playPauseLabel}
   174→          accessibilityHint={
   175→            isPlayPauseDisabled
   176→              ? 'Button is disabled. Start a session from the desktop app.'
   177→              : undefined
   178→          }
   179→          testID={`${testID}-play-pause`}
   180→        />
   181→
   182→        {/* Skip Interval Button */}
   183→        <IconButton
   184→          icon={<Icon name="play-skip-forward" />}
   185→          variant={skipVariant}
   186→          size="large"
   187→          circular
   188→          onPress={handleSkipPress}
   189→          disabled={isSkipDisabled}
   190→          loading={isSkipLoading}
   191→          accessibilityLabel="Skip to next interval"
   192→          accessibilityHint={
   193→            isSkipDisabled
   194→              ? isWorkout
   195→                ? 'Cannot skip. You are on the last interval.'
   196→                : 'Skip is only available during structured workouts.'
   197→              : 'Skip to the next interval in the workout.'
   198→          }
   199→          testID={`${testID}-skip`}
   200→        />
   201→
   202→        {/* Stop Button */}
   203→        <IconButton
   204→          icon={<Icon name="stop" />}
   205→          variant={stopVariant}
   206→          size="large"
   207→          circular
   208→          onPress={handleStopPress}
   209→          disabled={isStopDisabled}
   210→          loading={isStopLoading}
   211→          accessibilityLabel="Stop session"
   212→          accessibilityHint={
   213→            isStopDisabled
   214→              ? 'No active session to stop.'
   215→              : 'Stop the current workout or free ride session.'
   216→          }
   217→          testID={`${testID}-stop`}
   218→        />
   219→      </View>
   220→    </View>
   221→  );
   222→}
   223→
   224→const styles = StyleSheet.create({
   225→  container: {
   226→    position: 'absolute',
   227→    left: 0,
   228→    right: 0,
   229→    bottom: 0,
   230→    borderTopWidth: 1,
   231→    paddingTop: 16,
   232→    paddingHorizontal: 24,
   233→  },
   234→  buttonContainer: {
   235→    flexDirection: 'row',
   236→    justifyContent: 'center',
   237→    alignItems: 'center',
   238→  },
   239→});
