   169→// ============================================================
   170→// WebSocket Protocol Types
   171→// ============================================================
   172→
   173→/**
   174→ * Request messages sent to the RustRide desktop app.
   175→ * Matches CompanionRequest from src/companion/types.rs
   176→ */
   177→export type CompanionRequest =
   178→  | { type: 'auth'; pin: string }
   179→  | { type: 'get_session_status' }
   180→  | { type: 'subscribe_metrics' }
   181→  | { type: 'unsubscribe_metrics' }
   182→  | { type: 'workout_pause' }
   183→  | { type: 'workout_resume' }
   184→  | { type: 'workout_skip' }
   185→  | { type: 'workout_stop' }
   186→  | { type: 'adjust_resistance'; delta: number }
   187→  | { type: 'get_ride_history'; limit: number; offset: number }
   188→  | { type: 'get_ride_details'; ride_id: string }
   189→  | { type: 'ping' };
   190→
   191→/**
   192→ * Error codes returned by the server.
   193→ * Matches CompanionErrorCode from src/companion/types.rs
   194→ */
   195→export type CompanionErrorCode =
   196→  | 'AUTH_REQUIRED'
   197→  | 'INVALID_PIN'
   198→  | 'NO_SESSION'
   199→  | 'SESSION_ACTIVE'
   200→  | 'UNKNOWN_COMMAND'
   201→  | 'INVALID_PARAMS'
   202→  | 'RATE_LIMITED'
   203→  | 'INTERNAL_ERROR';
   204→
   205→/**
   206→ * Response messages received from the RustRide desktop app.
   207→ * Matches CompanionResponse from src/companion/types.rs
   208→ */
   209→export type CompanionResponse =
   210→  | { type: 'auth_ok'; session_id: string }
   211→  | { type: 'auth_failed'; reason: string }
   212→  | { type: 'session_status'; active: boolean; session: SessionStatusInfo | null }
   213→  | { type: 'subscribed_metrics' }
   214→  | { type: 'unsubscribed_metrics' }
   215→  | { type: 'command_ok'; command: string }
   216→  | { type: 'command_failed'; command: string; error: string }
   217→  | { type: 'ride_history'; rides: RideSummary[]; total: number }
   218→  | { type: 'ride_details'; ride: RideDetailInfo }
   219→  | { type: 'pong' }
   220→  | { type: 'error'; code: CompanionErrorCode; message: string };
   221→
   222→/**
   223→ * Event messages pushed from the RustRide desktop app.
   224→ * Matches CompanionEvent from src/companion/types.rs
   225→ */
   226→export type CompanionEvent =
   227→  | {
   228→      type: 'metrics';
   229→      power_watts: number | null;
   230→      heart_rate_bpm: number | null;
   231→      cadence_rpm: number | null;
   232→      speed_kmh: number | null;
   233→      distance_km: number;
   234→      elapsed_secs: number;
   235→      calories: number;
   236→    }
   237→  | {
   238→      type: 'session_state_changed';
   239→      state: 'idle' | 'starting' | 'active' | 'paused' | 'stopping' | 'completed';
   240→      session: SessionStatusInfo | null;
   241→    }
   242→  | {
   243→      type: 'interval_changed';
   244→      interval_index: number;
   245→      total_intervals: number;
   246→      interval_name: string;
   247→      target_power_watts: number;
   248→      duration_secs: number;
   249→    }
   250→  | {
   251→      type: 'disconnecting';
   252→      reason: string;
   253→    };
   254→
   255→/**
   256→ * Union type for all possible WebSocket messages from the server
   257→ */
   258→export type ServerMessage = CompanionResponse | CompanionEvent;
   259→
   260→/**
   261→ * Helper to check if a message is an event (vs response)
   262→ */
   263→export function isCompanionEvent(message: ServerMessage): message is CompanionEvent {
   264→  return (
   265→    message.type === 'metrics' ||
   266→    message.type === 'session_state_changed' ||
   267→    message.type === 'interval_changed' ||
   268→    message.type === 'disconnecting'
   269→  );
   270→}
   271→
   272→/**
   273→ * Helper to check if a message is a response
   274→ */
   275→export function isCompanionResponse(message: ServerMessage): message is CompanionResponse {
   276→  return !isCompanionEvent(message);
   277→}
